INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-relevo-de-los-calzados', 'El Relevo de los Calzados', 'Dinámica de agilidad física y velocidad donde los participantes recuperan y se abrochan sus zapatillas desde un montón central.', '<h2>📜 Descripción de El Relevo de los Calzados</h2>
<p><b>El Relevo de los Calzados</b> es una dinámica de destreza motriz, rapidez física y juego en equipo en salón o exterior. Todos los participantes se descalzan y colocan sus zapatillas mezcladas en un gran montón al centro del salón. Se delimita un círculo de 3 a 4 metros de radio alrededor del montón, y los jugadores se ubican por fuera del perímetro.</p>
<p>A la señal del animador, los participantes corren hacia el montón, buscan únicamente <b>una</b> de sus zapatillas, salen corriendo del círculo para ponérsela y abrocharla, y recién entonces regresan por el segundo calzado para ponérselo por completo antes de cruzar la meta.</p>
<p>Esta actividad ejercita los reflejos, la movilidad rápida, el orden de vestimenta y el entusiasmo alegre en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Relevo de los Calzados?</h2>
<p>Para llevar a cabo la dinámica con velocidad, entusiasmo y orden, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Depósito de Zapatillas:</b> Todos se quitan el calzado y lo amontonan al centro.</li>
  <li><b>Línea de Perímetro:</b> Los jugadores se ubican tras la línea divisoria a 4 metros de distancia.</li>
  <li><b>Carrera por el Primer Calzado:</b> A la señal, corren a buscar 1 zapatilla propia y salen del círculo a ponérsela.</li>
  <li><b>Regreso por la Segunda:</b> Una vez abrochada la primera, vuelven al montón por la segunda zapatilla.</li>
  <li><b>Cierre y Calzado Completo:</b> Gana quien quede totalmente calzado con sus cordones amarrados correctamente.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Relevo de los Calzados</h2>
<p>La actividad valora la agilidad física y el orden en el Tally:</p>
<ul>
  <li><b>Primer Calzado Completo:</b> Otorgar 5 puntos al scout que logre ponerse ambas zapatillas correctamente abrochadas.</li>
  <li><b>Orden y Cordones Firmes:</b> Otorgar 3 puntos a la patrulla que presente a todos sus miembros calzados sin cordones sueltos.</li>
  <li><b>Espíritu Alegre de Equipo:</b> Otorgar 3 puntos al equipo con mayor entusiasmo y respeto en la carrera.</li>
</ul>', '/uploads/el-relevo-de-los-calzados.webp', 'publicado', '{"areas": ["corporalidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "15 minutos", "cantidad": "05 participantes", "lugares": ["Interior", "Salón", "Exterior", "Cancha"], "materiales": ["Zapatillas"], "objetivos": ["Estimular la agilidad", "Desfogue de Energías", "Estimular la coordinación", "Trabajo en equipo"], "justificacion_areas": "El Relevo de los Calzados potencia la corporalidad al ejercitar la velocidad de desplazamiento, la motricidad fina en el amarrado de cordones y el desarrollo físico. Desarrolla la sociabilidad al fomentar el entusiasmo cooperativo y el respeto a las reglas de la carrera.", "variaciones": "<b>Relevo a Ciegas (Para Tropa/Avanzada):</b> Para incrementar la dificultad, los participantes buscan sus zapatillas con los ojos vendados.<br><b>Relevo por Seisenas/Patrullas:</b> Los miembros corren uno a la vez en formato de posta entregando el turno al estar calzados.<br><b>Amarre de Nudo Doble Obligatorio:</b> Exigir que los cordones tengan nudo ciego firme antes de dar la carrera por válida.", "recomendaciones": "Asegurar que el piso no esté resbaladizo para evitar tropezones al correr descalzos.", "objetivos_educativos": [{"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Corriendo rápido a buscar mi zapatilla y amarrándome los cordones yo solo con firmeza."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando la regla de ponerse primero una zapatilla fuera del círculo antes de buscar la otra."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Usando mis manos con soltura para ponerme el calzado y amarrar los cordones bien firmes."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Esperando mi turno detrás de la línea sin empujar a mis compañeros de seisena."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me gusta hacer actividades al aire libre.", "como_se_cumple": "Participando activamente en la carrera de calzados para ejercitar la agilidad física y la velocidad."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando juego limpio y respeto por las reglas al buscar el calzado en el montón central."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Compañía", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Coordinando la rapidez de pies y manos para lograr el amarrado correcto bajo presión de tiempo."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Alentando con entusiasmo y fraternidad el esfuerzo de todas las compañeras de equipo."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Tropa", "unidad": "Tropa", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Participando activamente en la carrera de calzados para ejercitar la agilidad física y la velocidad."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando juego limpio y respeto por las reglas al buscar el calzado en el montón central."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "como_se_cumple": "Coordinando la rapidez de pies y manos para lograr el amarrado correcto bajo presión de tiempo."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Alentando con entusiasmo y fraternidad el esfuerzo de todos los compañeros de equipo."}, {"id": "fe57c89e-be7b-46a1-b370-64df400355fa", "area": "Corporalidad", "unidad": "Avanzada", "texto": "Trato de aprender más sobre cuestiones técnicas relacionadas con el sonido, la imagen, la mecánica, la informática y otros.", "como_se_cumple": "Liderando la agilidad de movimiento y la destreza en dinámicas de relevos."}, {"id": "7e7417a5-a16e-4ff3-843f-93e711d017d4", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Promoviendo el clima alegre y la sana competencia en la Avanzada."}, {"id": "29eee8b1-a414-4df9-90e1-520a384fb9aa", "area": "Corporalidad", "unidad": "Clan", "texto": "Uno los conocimientos teórico y práctico mediante la aplicación constante de mis habilidades técnicas y manuales.", "como_se_cumple": "Fomentando el desahogo de energía y la agilidad motriz en actividades del Clan."}, {"id": "c4f78e61-6790-4cf4-b477-993900b5bf02", "area": "Sociabilidad", "unidad": "Clan", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Fomentando la integración alegre y la salud física mediante carreras dinámicas."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

